// Input: HTTP Request node output with raw HTML in `data`
const html = $input.first().json.data || $input.first().json.body || '';

const results = [];
const seenUrls = new Set();

// Matches: <h3 class="title...">\n <a href="URL">HEADLINE</a>\n</h3>
const titleRegex = /<h3 class="title[^"]*">\s*<a href="([^"]+)">\s*([\s\S]*?)\s*<\/a>\s*<\/h3>/g;

let match;
while ((match = titleRegex.exec(html)) !== null) {
  const articleUrl = match[1].replace(/&amp;/g, '&');
  const headline = match[2].replace(/\s+/g, ' ').trim();

  if (!headline || seenUrls.has(articleUrl)) continue; // skip empty/dupe
  seenUrls.add(articleUrl);

  // Look at a window of HTML *before* this headline to find its image + author
  const windowStart = Math.max(0, match.index - 3000);
  const context = html.slice(windowStart, match.index);

  // Image: last <img ... data-original="..."> before the headline
  const imgMatches = [...context.matchAll(/data-original="([^"]+)"/g)];
  const imageUrl = imgMatches.length ? imgMatches[imgMatches.length - 1][1].replace(/&amp;/g, '&') : 'https://images.unsplash.com/photo-1504711434969-e33886168f5c?auto=format&fit=crop&w=1200&q=80';

  // Author: last <a class="person-name...">NAME</a> before the headline
  const authorMatches = [...context.matchAll(/class="person-name[^"]*"[^>]*>\s*([^<]+?)\s*<\/a>/g)];
  const author = authorMatches.length ? authorMatches[authorMatches.length - 1][1].trim() : 'News Desk Correspondent';

  // Auto Category Classifier
  const lowerH = headline.toLowerCase();
  let category = 'General News';
  if (/\b(parliament|senate|congress|court|election|bill|minister|law)\b/i.test(lowerH)) category = 'Political: National';
  else if (/\b(un|summit|treaty|foreign|global|diplomacy|border)\b/i.test(lowerH)) category = 'Political: International';
  else if (/\b(match|cup|championship|goal|league|trophy|cricket|tennis|football|sports)\b/i.test(lowerH)) category = 'Sports';
  else if (/\b(movie|film|grammy|oscar|song|music|actor|cinema|premiere)\b/i.test(lowerH)) category = 'Entertainment';
  else if (/\b(ai|quantum|telescope|tech|space|robot|cyber|software)\b/i.test(lowerH)) category = 'Science & Tech';
  else if (/\b(market|stock|bank|inflation|economy|invest|billion)\b/i.test(lowerH)) category = 'Business & Economy';
  else if (/\b(climate|coral|carbon|ocean|forest|green|emissions)\b/i.test(lowerH)) category = 'Climate & World';

  results.push({
    "Headline": headline,
    "Image URL": imageUrl,
    "Author": author,
    "Article URL": articleUrl.startsWith('http') ? articleUrl : `https://apnews.com${articleUrl}`,
    "Category": category,
    "Date": new Date().toISOString().split('T')[0],
    "Source": "AP News Wire"
  });
}

return results.map(item => ({ json: item }));
